function Yargi.MakePermanent()
	pcall(function()
		local lgd_wpn = package.loaded["client.slua.logic.wardrobe.logic_legend_weapon"] or _G.logic_legend_weapon
		if not lgd_wpn then
			local ok, res = pcall(require, "client.slua.logic.wardrobe.logic_legend_weapon")
			if ok then lgd_wpn = res end
		end
		if lgd_wpn then
			if lgd_wpn.GetPermissionType then
				lgd_wpn.GetPermissionType = function() return 4 end
			end
			if lgd_wpn.GetActivateStatus then
				lgd_wpn.GetActivateStatus = function() return 4 end
			end
			if lgd_wpn.IsLgdWpnValid then
				lgd_wpn.IsLgdWpnValid = function() return true end
			end
			if lgd_wpn.CheckValidity then
				lgd_wpn.CheckValidity = function() return true end
			end
			if lgd_wpn._HasPermanentCard then
				lgd_wpn._HasPermanentCard = function() return true end
			end
		end
	end)
	
	pcall(function()
		local lgd_suit = package.loaded["client.slua.logic.wardrobe.logic_legend_suit"] or _G.logic_legend_suit
		if not lgd_suit then
			local ok, res = pcall(require, "client.slua.logic.wardrobe.logic_legend_suit")
			if ok then lgd_suit = res end
		end
		if lgd_suit then
			if lgd_suit.GetPermissionType then
				lgd_suit.GetPermissionType = function() return 4 end
			end
			if lgd_suit.GetActivateStatus then
				lgd_suit.GetActivateStatus = function() return 4 end
			end
			if lgd_suit.IsLgdSuitValid then
				lgd_suit.IsLgdSuitValid = function() return true end
			end
			if lgd_suit.CheckValidity then
				lgd_suit.CheckValidity = function() return true end
			end
			if lgd_suit._HasPermanentCard then
				lgd_suit._HasPermanentCard = function() return true end
			end
		end
	end)
	
	pcall(function()
		local xsuit = package.loaded["client.slua.logic.xsuit.logic_xsuit"] or _G.logic_xsuit
		if not xsuit then
			local ok, res = pcall(require, "client.slua.logic.xsuit.logic_xsuit")
			if ok then xsuit = res end
		end
		if xsuit then
			if xsuit.IsLgdSuitValid then xsuit.IsLgdSuitValid = function() return true end end
			if xsuit.CheckValidity then xsuit.CheckValidity = function() return true end end
		end
	end)
	
	-- Ağa giden giyme/çıkarma isteklerini yakalayıp sahte başarılı cevap döndürüyoruz! (Eşyanın karakterin üzerine gelmesi için kritik!)
	pcall(function()
		local WardRobeHandler = package.loaded["client.network.Protocol.WardRobeHandler"] or _G.WardRobeHandler
		if not WardRobeHandler then
			local ok, res = pcall(require, "client.network.Protocol.WardRobeHandler")
			if ok then WardRobeHandler = res end
		end
		
		if WardRobeHandler and WardRobeHandler.send_depot_put_on_req and not WardRobeHandler._yargiHookedPutOn then
			WardRobeHandler._yargiHookedPutOn = true
			
			local old_put_on = WardRobeHandler.send_depot_put_on_req
			WardRobeHandler.send_depot_put_on_req = function(insID, extra)
				if tonumber(insID) >= Yargi.FakeInstBase then
					local fakeItems = Yargi.GetFallbackPacket()
					local itemData = fakeItems[tonumber(insID)]
					if itemData then
						itemData.instid = tonumber(insID)
						local wardrobeLogic = require("client.slua.logic.wardrobe.logic_wardrobe_new")
						wardrobeLogic:on_puton_rsp(0, itemData, nil, nil, extra)
						return
					end
				end
				if old_put_on then return old_put_on(insID, extra) end
			end
			
			local old_put_down = WardRobeHandler.send_depot_put_down_req
			WardRobeHandler.send_depot_put_down_req = function(insID)
				if tonumber(insID) >= Yargi.FakeInstBase then
					local fakeItems = Yargi.GetFallbackPacket()
					local itemData = fakeItems[tonumber(insID)]
					if itemData then
						itemData.instid = tonumber(insID)
						local wardrobeLogic = require("client.slua.logic.wardrobe.logic_wardrobe_new")
						wardrobeLogic:on_putdown_rsp(0, itemData)
						return
					end
				end
				if old_put_down then return old_put_down(insID) end
			end
		end
	end)
end

function Yargi.HookWardrobeData(module)
	if type(module) ~= "table" or module._yargiHooked then return end
	module._yargiHooked = true
	local old_InitHallDepotData = module.InitHallDepotData
	if old_InitHallDepotData then
		module.InitHallDepotData = function(self, arrayItemDataPackage)
			-- Pre-Injection: Oyun motoru paketi işlemeden ve UI'a yansıtmadan ÖNCE araya giriyoruz!
			pcall(function()
				if arrayItemDataPackage and type(arrayItemDataPackage) == "table" then
					local fakePacket = Yargi.GetFallbackPacket()
					-- Eğer paket listesinde hiç eleman yoksa, ilk sıraya fakePacket'i koyuyoruz
					if #arrayItemDataPackage == 0 then
						arrayItemDataPackage[1] = fakePacket
					else
						-- Eğer paket listesinde eleman varsa, ilk haritanın içine kendi eşyalarımızı sızdırıyoruz
						local firstMap = arrayItemDataPackage[1]
						if type(firstMap) == "table" then
							for k, v in pairs(fakePacket) do
								firstMap[k] = v
							end
						else
							table.insert(arrayItemDataPackage, fakePacket)
						end
					end
				elseif type(arrayItemDataPackage) == "userdata" and arrayItemDataPackage.Add then
					local fakePacket = Yargi.GetFallbackPacket()
					arrayItemDataPackage:Add(fakePacket)
				end
			end)
			
			-- Şimdi orijinal fonksiyonu çağırıyoruz, oyun kendi kendine bizim eşyalarımızı da yükleyecek ve UI güncellenecek!
			local ret = old_InitHallDepotData(self, arrayItemDataPackage)
			
			return ret
		end
	end
end

function Yargi.Init()
	if not _G.YARGI_ALIVE then return end

	local old_require = _G.require
	_G.require = function(name)
		local module = old_require(name)
		local ok, err = pcall(function()
			if name == "client.slua.logic.wardrobe.wardrobe_data" then
				Yargi.HookWardrobeData(module)
			end
		end)
		return module
	end

	local existing = package.loaded["client.slua.logic.wardrobe.wardrobe_data"]
	if existing then
		Yargi.HookWardrobeData(existing)
	end
	
	Yargi.MakePermanent()
end

function Yargi.ShowInjectSuccess()
	pcall(function()
		local GlobalUIFunctionLibrary = _G.GlobalUIFunctionLibrary or require("client.slua.umg.common.GlobalUIFunctionLibrary")
		if GlobalUIFunctionLibrary and GlobalUIFunctionLibrary.ShowSystemTips then
			GlobalUIFunctionLibrary.ShowSystemTips("Lua inject ✓")
			GlobalUIFunctionLibrary.ShowSystemTips("Lua inject ✓")
		end
	end)
	
	pcall(function()
		local IngameTipsTools = package.loaded["client.slua.logic.common.IngameTipsTools"] or _G.IngameTipsTools
		if not IngameTipsTools then
			local ok, res = pcall(require, "client.slua.logic.common.IngameTipsTools")
			if ok then IngameTipsTools = res end
		end
		
		if IngameTipsTools and IngameTipsTools.ShowMsgBox then
			IngameTipsTools.ShowMsgBox(1, "YARGI ENGINE", "Lua inject ✓", function() end)
		end
	end)
end

Yargi.Init()
Yargi.ShowInjectSuccess()
return Yargi